const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const furnaceCreek = ee.Geometry.Point(-116.8679, 36.4600); // Approximate coordinates for Furnace Creek Visitor's Center
    const startDate = '2013-06-30T00:00:00';
    const endDate = '2013-06-30T23:59:59'; // End of the day

    // 2. Data Acquisition
    let era5Collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterBounds(furnaceCreek)
      .filterDate(startDate, endDate)
      .select('temperature_2m');

    // Check if the collection is empty
    const collectionSize = await era5Collection.size().getInfo();
    if (collectionSize === 0) {
      console.log("No ERA5-Land hourly data found for June 30, 2013 at Furnace Creek.");
      console.log("C1");
      return;
    }
    console.log(`Images found for June 30, 2013: ${collectionSize}`);

    // Convert temperature from Kelvin to Celsius for each image
    const tempCelsiusCollection = era5Collection.map(image => {
      const tempK = image.select('temperature_2m');
      const tempC = tempK.subtract(273.15).rename('temperature_2m_celsius');
      return image.addBands(tempC);
    });

    // Find the maximum temperature for the day at the point
    const maxTempImage = tempCelsiusCollection.max();

    // 3. Processing and Calculation
    const maxTempResult = await maxTempImage.reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: furnaceCreek,
      scale: 11132, // ERA5-Land native resolution is ~11.1 km
      maxPixels: 1e9
    }).get('temperature_2m_celsius').getInfo();

    // 4. Validation & Final Answer
    if (maxTempResult === null || typeof maxTempResult === 'undefined' || isNaN(maxTempResult)) {
      console.log("Calculation failed: Could not retrieve maximum temperature.");
      console.log("C3");
      return;
    }

    console.log(`Max daily temperature at Furnace Creek on June 30, 2013: ${maxTempResult.toFixed(2)} °C`);

    const threshold = 58; // degrees Celsius
    if (maxTempResult > threshold) {
      console.log("A"); // Yes, it reached over 58 degrees Celsius
    } else {
      console.log("B"); // No, it did not reach over 58 degrees Celsius
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
